const DEFAULT_PB_GUILDS=JSON.parse(readFileSync(join(here,'../../../data/pb/guild-defaults.json'),'utf8'));
function pbGuildCatalogue(value:any){return mergeGuildCatalogue(DEFAULT_PB_GUILDS,json(value,[]));}
